def mean_variance(values):
    """Return mean and sample variance; require at least two values."""
    if len(values) < 2:
        raise ValueError("At least two values are required")
    total = 0
    for value in values:
        total += value
    mean = total / len(values)
    squares = 0
    for value in values:
        squares += (value - mean) ** 2
    return mean, squares / (len(values) - 1)

