total = 0
with open("fishtotals.txt") as infile, open("flounder.txt", "w") as outfile:
    for line in infile:
        if not line.strip():
            continue
        fisherman, catches = line.strip().split(":", 1)
        kept = []
        for catch in catches.split(","):
            fields = catch.strip().split()
            if fields and fields[0].lower() == "flounder":
                kept.append(" ".join(fields))
                total += 1
        if kept:
            outfile.write(f"{fisherman}: {', '.join(kept)}\n")
    outfile.write(f"Total: {total} flounders caught\n")

